/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNumberArray = require( '@stdlib/assert/is-number-array' );
var isEmptyArray = require( '@stdlib/assert/is-empty-array' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Sets the rendering mode.
*
* @private
* @param {Array} value - Array of size 2 indicate the x axis data range
* @throws {TypeError} must be a boolean
*/
function set( value ) {
	var range;

	range = this._xAxisDataObj.range;
	if ( !isEmptyArray( value ) || !isNumberArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a array of number. Value: `%s`.', 'xaxisData', value ) );
	}
	if ( value[ 0 ] !== range[0] || value[ 1 ] !== range[ 1 ] ) {
		range[ 0 ] = value[ 0 ];
		range[ 1 ] = value[ 1 ];
		if ( !this._quiet ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
